+    const connection = new EventEmitter();
+    queueMicrotask(() => connection.emit("error", new Error("not listening")));
+    return connection;
+  });
+});
+
+afterEach(() => {
+  vi.restoreAllMocks();
+  rmSync(ixHome, { recursive: true, force: true });
