+    chmodSync(path, 0o200);
+
+    expect(() =>
+      writeJsonConfig(path, (config) => {
+        (config.mcpServers as unknown) = { "ix-memory": { command: "ix" } };
+      }),
+    ).toThrow(/EACCES/);
+
+    chmodSync(path, 0o600);
+    expect(JSON.parse(readFileSync(path, "utf8")).mcpServers.theirs.command).toBe("other");
