+
+export async function runInstall(options: InstallOptions = {}): Promise<InstallReport> {
+  const hosts = (options.hosts ?? createHosts(writeJsonConfig)).filter(
+    (host) => !options.only?.length || options.only.includes(host.id),
+  );
