+
+function registerSymbolTool(
+  server: McpServer,
+  runIx: IxRunner,
+  name: string,
+  description: string,
+  command: string,
+): void {
+  registerTool(server, name, description, { symbol: z.string().min(1) }, async (input) =>
+    runFormatted(runIx, name, [command, stringArg(input, "symbol")]),
+  );
