+
+function registerTool(
+  server: McpServer,
+  name: string,
+  description: string,
+  inputSchema: z.ZodRawShape,
+  handler: (input: ToolInput) => Promise<CallToolResult>,
+): void {
+  server.registerTool(name, { description, inputSchema }, async (input) =>
+    handler(input as ToolInput),
+  );
