+    const extensionlessSuffixes =
+      kind === "types"
+        ? SOURCE_SUFFIXES
+        : preferJavaScript
+          ? [".js", ".jsx", ".mjs", ".cjs", ".ts", ".tsx", ".d.ts"]
+          : [".ts", ".tsx", ".js", ".jsx", ".d.ts", ".mjs", ".cjs"];
