+        }
+        return [];
+      }
+      if (config.baseUrl) {
+        const matches = resolveCandidate(
+          nodePath.resolve(config.baseUrl, specifier),
+          sourcePath,
+          kind,
+        );
+        if (matches.length > 0) return matches;
+      }
+    }
+    return config?.baseUrl ? [] : undefined;
+  };
+}

